  const unconfirmed = live({ applied: pairingApplication(pairingEditions[0], false), candidates: live().candidates.map(entry => entry.status === 'unverified'
    ? { ...entry, comparison: { ...entry.comparison!, unknownLocalDurations: 2, subset: { ...entry.comparison!.subset!, pairing: 'unique', pairs: [] } } } : entry) });
  onChoose = mountReview(unconfirmed, liveReview);
  const card = within(screen.getByRole('region', { name: /^Possible match/ }));
  expect(card.getByText('The tracks pair in exactly one way, but 2 have no duration, so the match was not confirmed automatically')).toBeInTheDocument();
